1	package retention
2	
3	import (
4		"errors"
5		"strings"
6		"testing"
7	)
8	
9	// 同一份档案自己的保存内容中，冻结列表 freezes 最多只能出现一次：普通解码对
10	// 同名字段只保留最后一个值，同一份档案记录中若先保存了包含未解除诉讼冻结的
11	// freezes、后面又保存一个空的 freezes，读取后历史里原冻结消失，到期后的销毁
12	// 前核对可能误报可以办理。Open 必须按保存记录损坏失败（ErrCorruptState），
13	// 错误指出档案编号，并说明重复的是冻结列表 freezes 本身，不能误报为冻结编号
14	// 重复；两处列表完全相同、分别保存不同冻结、其中一处为空列表或 null 都按同一
15	// 规则拒绝，不合并、不挑选其中一份，调整保存顺序也不能改变拒绝结果，原文件
16	// 保持原样。
17	func TestOpenRejectsDuplicateFreezesField(t *testing.T) {
18		activeFreeze := `{"id":"F-1","reason":"诉讼","frozen_on":"2025-01-05","released":false}`
19		releasedFreeze := `{"id":"F-2","reason":"保全","frozen_on":"2025-01-06","released":true,"release_reason":"结案","released_on":"2025-01-08"}`
20		// rec 构造一份登记记录，freezesFields 是原样拼接进记录的冻结列表字段
21		// （可以写零个、一个或多个，字段名写法与列表内容任意）。
22		rec := func(id string, freezesFields ...string) string {
23			fields := `"id":"` + id + `","category":"合同","start":"2020-01-01","end":"2025-01-10","initial_end":"2025-01-10","destroyed":false`
24			for _, f := range freezesFields {
25				fields += "," + f
26			}
27			return `{` + fields + `}`
28		}
29		state := func(archiveRec string) string {
30			return `{"version":1,"archives":{"A-1":` + archiveRec + `},"manifests":{}}`
31		}
32	
33		corrupt := map[string]string{
34			"先保存未解除冻结后保存空列表": state(rec("A-1", `"freezes":[`+activeFreeze+`]`, `"freezes":[]`)),
35			"保存顺序相反同样拒绝":     state(rec("A-1", `"freezes":[]`, `"freezes":[`+activeFreeze+`]`)),
36			"两处列表完全相同":       state(rec("A-1", `"freezes":[`+activeFreeze+`]`, `"freezes":[`+activeFreeze+`]`)),
37			"两处分别保存不同冻结":     state(rec("A-1", `"freezes":[`+activeFreeze+`]`, `"freezes":[`+releasedFreeze+`]`)),
38			"第二处为空列表":        state(rec("A-1", `"freezes":[`+activeFreeze+`]`, `"freezes":[]`)),
39			"第一处为空列表":        state(rec("A-1", `"freezes":[]`, `"freezes":[`+activeFreeze+`]`)),
40			"第二处为null":       state(rec("A-1", `"freezes":[`+activeFreeze+`]`, `"freezes":null`)),
41			"第一处为null":       state(rec("A-1", `"freezes":null`, `"freezes":[`+activeFreeze+`]`)),
42			"两处都为null":       state(rec("A-1", `"freezes":null`, `"freezes":null`)),
43			// 反引号字符串里的 \u0066 是字面的反斜杠+u0066，JSON 解码后才是字符 f，
44			// 与直接写出的 freezes 是同一个字段名。
45			"大小写写法混用重复":   state(rec("A-1", `"Freezes":[`+activeFreeze+`]`, `"freezes":[]`)),
46			"大小写写法混用顺序相反": state(rec("A-1", `"freezes":[`+activeFreeze+`]`, `"Freezes":[]`)),
47			"冻结列表出现三次":    state(rec("A-1", `"freezes":[`+activeFreeze+`]`, `"freezes":[]`, `"freezes":null`)),
48		}
49		// 转义写法需要字面反斜杠，单独构造。
50		corrupt["Unicode转义字段名与直接字段名重复"] = state(rec("A-1", `"freezes":[`+activeFreeze+`]`, `"\u0066reezes":[]`))
51		corrupt["Unicode转义字段名与直接字段名重复顺序相反"] = state(rec("A-1", `"\u0066reezes":[]`, `"freezes":[`+activeFreeze+`]`))
52	
53		for name, content := range corrupt {
54			t.Run(name, func(t *testing.T) {
55				dir := t.TempDir()
56				writeStateFile(t, dir, content)
57	
58				s, err := Open(dir)
59				if err == nil {
60					s.Close()
61					t.Fatal("单份档案的保存内容中出现两次冻结列表时不应打开成功")
62				}
63				if !errors.Is(err, ErrCorruptState) {
64					t.Fatalf("错误应可判定为 ErrCorruptState，得到 %v", err)
65				}
66				msg := err.Error()
67				if !strings.Contains(msg, "A-1") {
68					t.Fatalf("错误信息应指出档案编号 A-1，得到 %v", err)
69				}
70				if !strings.Contains(msg, "freezes") || !strings.Contains(msg, "冻结列表") {
71					t.Fatalf("错误信息应说明重复的是冻结列表 freezes，得到 %v", err)
72				}
73				// 不得误报为冻结编号重复：重复的是列表字段本身，与冻结编号无关。
74				if strings.Contains(msg, "冻结编号") {
75					t.Fatalf("错误信息不应误报为冻结编号重复，得到 %v", err)
76				}
77				if got := readStateFile(t, dir); got != content {
78					t.Fatalf("打开失败后原文件被改动:\n%q", got)
79				}
80			})
81		}
82	
83		// 对照组：冻结列表缺省、仅一次为 null 或仅有一个空列表时继续表示没有冻结；
84		// 现有能识别为冻结列表的大小写写法与转义写法单独出现时继续可读；不同档案各自
85		// 的冻结列表不合在一起计数；合法列表里的全部冻结和解除历史按原顺序保留。
86		t.Run("合法记录对照组", func(t *testing.T) {
87			valid := map[string]string{
88				"冻结列表缺省":           state(rec("A-1")),
89				"freezes仅一次为null":  state(rec("A-1", `"freezes":null`)),
90				"仅有一个空列表":          state(rec("A-1", `"freezes":[]`)),
91				"大小写写法Freezes单独出现": state(rec("A-1", `"Freezes":[`+activeFreeze+`]`)),
92				"大小写写法FREEZES单独出现": state(rec("A-1", `"FREEZES":[`+activeFreeze+`]`)),
93				// 不同档案各自带自己的冻结列表是正常保存格式，不合在一起计数。
94				"不同档案各自一个冻结列表": `{"version":1,"archives":{"A-1":` + rec("A-1", `"freezes":[`+activeFreeze+`]`) +
95					`,"A-2":{"id":"A-2","category":"凭证","start":"2020-01-01","end":"2025-06-30","initial_end":"2025-06-30","destroyed":false,"freezes":[` + releasedFreeze + `]}},"manifests":{}}`,
96				// 合法列表里的全部冻结和解除历史按原顺序保留。
97				"合法列表保留全部冻结与解除历史": state(rec("A-1", `"freezes":[`+activeFreeze+`,`+releasedFreeze+`]`)),
98			}
99			// 转义写法需要字面反斜杠，单独构造。
100			valid["Unicode转义字段名单独出现"] = state(rec("A-1", `"\u0066reezes":[`+activeFreeze+`]`))
101			for name, content := range valid {
102				t.Run(name, func(t *testing.T) {
103					dir := t.TempDir()
104					writeStateFile(t, dir, content)
105					s, err := Open(dir)
106					if err != nil {
107						t.Fatalf("合法记录应能打开: %v", err)
108					}
109					defer s.Close()
110				})
111			}
112		})
113	
114		// 合法列表里的全部冻结和解除历史仍按原顺序保留，未解除冻结继续阻止销毁。
115		t.Run("合法列表内容完整保留", func(t *testing.T) {
116			dir := t.TempDir()
117			writeStateFile(t, dir, state(rec("A-1", `"freezes":[`+activeFreeze+`,`+releasedFreeze+`]`)))
118			s, err := Open(dir)
119			if err != nil {
120				t.Fatalf("合法记录应能打开: %v", err)
121			}
122			defer s.Close()
123			h, found, err := s.History("A-1")
124			if err != nil || !found {
125				t.Fatalf("查询应成功: found=%v err=%v", found, err)
126			}
127			if len(h.Freezes) != 2 || h.Freezes[0].ID != "F-1" || h.Freezes[1].ID != "F-2" {
128				t.Fatalf("冻结历史应按原顺序保留 F-1、F-2: %+v", h.Freezes)
129			}
130			if h.Freezes[0].Released || !h.Freezes[1].Released || h.Freezes[1].ReleaseReason != "结案" {
131				t.Fatalf("解除历史应完整保留: %+v", h.Freezes)
132			}
133			if len(h.ActiveFreezes) != 1 || h.ActiveFreezes[0].ID != "F-1" {
134				t.Fatalf("未解除冻结应只剩 F-1: %+v", h.ActiveFreezes)
135			}
136			r, err := s.Check(CheckRequest{
137				ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
138			})
139			if err != nil || r.Status != CheckBlocked {
140				t.Fatalf("未解除冻结仍应阻止销毁: %+v err=%v", r, err)
141			}
142		})
143	
144		// 已销毁档案同样适用：已销毁档案的保存内容中出现两次冻结列表也按损坏拒绝；
145		// 只出现一次的合法已销毁档案（冻结均已解除）继续可读。
146		t.Run("已销毁档案同样适用", func(t *testing.T) {
147			manifest := `{"application_id":"APP-1","processed_on":"2025-01-10","entries":[{"id":"A-1","category":"合同","start":"2020-01-01","end":"2025-01-10"}]}`
148			destroyedRec := func(freezesFields ...string) string {
149				fields := `"id":"A-1","category":"合同","start":"2020-01-01","end":"2025-01-10","initial_end":"2025-01-10","destroyed":true,"manifest_id":"APP-1"`
150				for _, f := range freezesFields {
151					fields += "," + f
152				}
153				return `{` + fields + `}`
154			}
155			stateWithManifest := func(archiveRec string) string {
156				return `{"version":1,"archives":{"A-1":` + archiveRec + `},"manifests":{"APP-1":` + manifest + `}}`
157			}
158	
159			dir := t.TempDir()
160			content := stateWithManifest(destroyedRec(`"freezes":[`+releasedFreeze+`]`, `"freezes":[]`))
161			writeStateFile(t, dir, content)
162			s, err := Open(dir)
163			if err == nil {
164				s.Close()
165				t.Fatal("已销毁档案的保存内容中出现两次冻结列表时不应打开成功")
166			}
167			if !errors.Is(err, ErrCorruptState) ||
168				!strings.Contains(err.Error(), "A-1") ||
169				!strings.Contains(err.Error(), "freezes") {
170				t.Fatalf("打开错误应为 ErrCorruptState 并指出档案编号与冻结列表 freezes，得到 %v", err)
171			}
172			if got := readStateFile(t, dir); got != content {
173				t.Fatalf("打开失败后原文件被改动:\n%q", got)
174			}
175	
176			// 对照：已销毁档案只保存一个冻结列表（冻结已合法解除）时继续可读。
177			dir2 := t.TempDir()
178			writeStateFile(t, dir2, stateWithManifest(destroyedRec(`"freezes":[`+releasedFreeze+`]`)))
179			s2, err := Open(dir2)
180			if err != nil {
181				t.Fatalf("合法的已销毁档案应能打开: %v", err)
182			}
183			defer s2.Close()
184			h, found, err := s2.History("A-1")
185			if err != nil || !found || !h.Destroyed || len(h.Freezes) != 1 {
186				t.Fatalf("已销毁档案的历史与冻结记录应完整可查: %+v found=%v err=%v", h, found, err)
187			}
188		})
189	}
190	
191	// 保管库打开后保存内容才出现重复的冻结列表：下一次使用有效输入查询历史、取回清册、
192	// 销毁前核对与各项办理都必须按整库记录损坏失败——即使操作的是另一份没有问题的
193	// 档案——不返回正常历史、清册或部分核对结果，不改变档案状态或生成清册，原保存
194	// 内容保持原样。
195	func TestDuplicateFreezesFieldAfterOpenFailsAllOperations(t *testing.T) {
196		dir := t.TempDir()
197		s, err := Open(dir)
198		if err != nil {
199			t.Fatal(err)
200		}
201		defer s.Close()
202		reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-10")
203		reg(t, s, "A-2", "凭证", "2020-01-01", "2025-06-30")
204		reg(t, s, "A-3", "单据", "2020-01-01", "2025-01-10")
205		if err := s.Freeze(FreezeInput{
206			ArchiveID: "A-1", FreezeID: "F-1", Reason: "诉讼", FrozenOn: MustParseDate("2025-01-05"),
207		}); err != nil {
208			t.Fatal(err)
209		}
210		// A-3 先冻结再解除、随后合法销毁，供损坏后验证“取回清册”同样整库失败。
211		if err := s.Freeze(FreezeInput{
212			ArchiveID: "A-3", FreezeID: "F-3", Reason: "保全", FrozenOn: MustParseDate("2025-01-06"),
213		}); err != nil {
214			t.Fatal(err)
215		}
216		if err := s.Release(ReleaseInput{
217			ArchiveID: "A-3", FreezeID: "F-3", Reason: "结案", ReleasedOn: MustParseDate("2025-01-08"),
218		}); err != nil {
219			t.Fatal(err)
220		}
221		if _, err := s.Destroy(DestructionRequest{
222			ApplicationID: "APP-3", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-3"},
223		}); err != nil {
224			t.Fatal(err)
225		}
226	
227		// 在 A-1 的登记记录里再写入一个冻结列表：先一个空列表、再是原来保存着
228		// 未解除冻结 F-1 的列表——普通解码会只剩后一个，但两处保存本身已使记录
229		// 不可信。档案编号按排序保存，A-1 的记录是文件中第一个 freezes 字段。
230		good := readStateFile(t, dir)
231		corrupt := strings.Replace(good, `"freezes"`, `"freezes": [],
232	      "freezes"`, 1)
233		if corrupt == good {
234			t.Fatal("未找到 A-1 记录的冻结列表位置，测试夹具失效")
235		}
236		writeStateFile(t, dir, corrupt)
237		corruptContent := readStateFile(t, dir)
238	
239		// 重新打开必须失败，错误指出档案编号并说明重复的是冻结列表 freezes。
240		s2, err := Open(dir)
241		if err == nil {
242			s2.Close()
243			t.Fatal("单份档案的保存内容中出现两个冻结列表时，打开必须失败")
244		}
245		if !errors.Is(err, ErrCorruptState) ||
246			!strings.Contains(err.Error(), "A-1") ||
247			!strings.Contains(err.Error(), "freezes") ||
248			!strings.Contains(err.Error(), "冻结列表") {
249			t.Fatalf("打开错误应为 ErrCorruptState 并指出档案 A-1 的冻结列表 freezes 重复，得到 %v", err)
250		}
251		if strings.Contains(err.Error(), "冻结编号") {
252			t.Fatalf("错误信息不应误报为冻结编号重复，得到 %v", err)
253		}
254	
255		// 已打开实例：即使本次只操作没有问题的正常档案 A-2，也必须按整库损坏失败。
256		if h, found, err := s.History("A-2"); !errors.Is(err, ErrCorruptState) || found || h.ID != "" {
257			t.Fatalf("损坏后查询无关档案也必须失败且无结论: found=%v err=%v", found, err)
258		}
259		if h, found, err := s.History("A-1"); !errors.Is(err, ErrCorruptState) || found || h.ID != "" {
260			t.Fatalf("损坏后 History 必须失败且不得给出部分历史: found=%v err=%v", found, err)
261		}
262		if m, found, err := s.GetManifest("APP-3"); !errors.Is(err, ErrCorruptState) || found || m.ApplicationID != "" {
263			t.Fatalf("损坏后 GetManifest 必须失败: found=%v err=%v %+v", found, err, m)
264		}
265		if r, err := s.Check(CheckRequest{
266			ApplicationID: "APP-9", ProcessedOn: MustParseDate("2025-06-30"), ArchiveIDs: []string{"A-2"},
267		}); !errors.Is(err, ErrCorruptState) || r.Status != "" || len(r.Results) != 0 {
268			t.Fatalf("损坏后 Check 必须失败且不得给出可以办理等结论或部分报告: %+v err=%v", r, err)
269		}
270		// 关键回归点：损坏状态下绝不能把重复保存的冻结列表当成没有冻结的依据，
271		// 在截止日当天给出可以办理甚至完成销毁。
272		if r, err := s.Check(CheckRequest{
273			ApplicationID: "APP-8", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
274		}); !errors.Is(err, ErrCorruptState) || r.Status != "" || len(r.Results) != 0 {
275			t.Fatalf("损坏后对 A-1 的核对也必须失败，不能误报可以办理: %+v err=%v", r, err)
276		}
277		if m, err := s.Destroy(DestructionRequest{
278			ApplicationID: "APP-9", ProcessedOn: MustParseDate("2025-06-30"), ArchiveIDs: []string{"A-2"},
279		}); !errors.Is(err, ErrCorruptState) || m.ApplicationID != "" {
280			t.Fatalf("损坏后 Destroy 必须失败且不得生成清册: %+v err=%v", m, err)
281		}
282		if m, err := s.Destroy(DestructionRequest{
283			ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
284		}); !errors.Is(err, ErrCorruptState) || m.ApplicationID != "" {
285			t.Fatalf("损坏后不得凭重复保存的冻结列表销毁 A-1: %+v err=%v", m, err)
286		}
287		// 已成功申请的幂等重放同样不能取回原清册。
288		if m, err := s.Destroy(DestructionRequest{
289			ApplicationID: "APP-3", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-3"},
290		}); !errors.Is(err, ErrCorruptState) || m.ApplicationID != "" {
291			t.Fatalf("损坏后已成功申请的重放也必须失败且不得返回原清册: %+v err=%v", m, err)
292		}
293		if err := s.Register(RegisterInput{
294			ID: "A-4", Category: "凭证", Start: MustParseDate("2020-01-01"), End: MustParseDate("2025-06-30"),
295		}); !errors.Is(err, ErrCorruptState) {
296			t.Fatalf("损坏后 Register 必须失败: %v", err)
297		}
298		if err := s.Freeze(FreezeInput{
299			ArchiveID: "A-2", FreezeID: "F-X", Reason: "诉讼", FrozenOn: MustParseDate("2025-06-01"),
300		}); !errors.Is(err, ErrCorruptState) {
301			t.Fatalf("损坏后 Freeze 必须失败: %v", err)
302		}
303		if err := s.Release(ReleaseInput{
304			ArchiveID: "A-1", FreezeID: "F-1", Reason: "结案", ReleasedOn: MustParseDate("2025-01-08"),
305		}); !errors.Is(err, ErrCorruptState) {
306			t.Fatalf("损坏后 Release 必须失败: %v", err)
307		}
308		if _, err := s.Revise(ReviseInput{
309			RevisionID: "R-9", ArchiveID: "A-2",
310			OriginalEnd: MustParseDate("2025-06-30"), NewEnd: MustParseDate("2026-06-30"),
311			RevisedOn: MustParseDate("2025-06-01"), Reason: "延期",
312		}); !errors.Is(err, ErrCorruptState) {
313			t.Fatalf("损坏后 Revise 必须失败: %v", err)
314		}
315	
316		// 失败不得触发修复：不合并两处列表、不挑选其中一份、不重新保存来消除重复，
317		// 原保存内容保持原样。
318		if got := readStateFile(t, dir); got != corruptContent {
319			t.Fatalf("失败后原保存内容被改动:\n%q", got)
320		}
321	
322		// 去掉重复的冻结列表后，合法记录恢复可用：A-1 的冻结历史仍是损坏前那一条
323		// 未解除冻结，不会被重复保存的空列表顶替；无关档案业务不受影响。
324		writeStateFile(t, dir, good)
325		h, found, err := s.History("A-1")
326		if err != nil || !found {
327			t.Fatalf("恢复后查询应成功: found=%v err=%v", found, err)
328		}
329		if len(h.Freezes) != 1 || h.Freezes[0].ID != "F-1" || h.Freezes[0].Released {
330			t.Fatalf("恢复后 A-1 应仍保留唯一一条未解除冻结 F-1: %+v", h.Freezes)
331		}
332		if r, err := s.Check(CheckRequest{
333			ApplicationID: "APP-8", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
334		}); err != nil || r.Status != CheckBlocked {
335			t.Fatalf("恢复后未解除冻结仍应阻止销毁 A-1: %+v err=%v", r, err)
336		}
337		if _, err := s.Destroy(DestructionRequest{
338			ApplicationID: "APP-2", ProcessedOn: MustParseDate("2025-06-30"), ArchiveIDs: []string{"A-2"},
339		}); err != nil {
340			t.Fatalf("恢复后无关档案应能正常办理销毁: %v", err)
341		}
342	}
