1	package retention
2	
3	import (
4		"errors"
5		"strings"
6		"testing"
7	)
8	
9	// 同一条冻结记录自己的保存内容中，解除标记 released 最多只能出现一次：普通解码
10	// 对同名字段只保留最后一个值，一条冻结若先写 released:false、后写 released:true
11	// 并带上合法的解除原因和解除日期，读取会采用后一个标记——档案到期后，销毁前
12	// 核对可能显示可以办理，正式销毁也会忽略这条冻结。Open 必须按保存记录损坏失败
13	// （ErrCorruptState），错误指出档案编号、冻结编号，并说明重复的是解除标记
14	// released 本身，不能误报为冻结编号或冻结列表重复；两处取值相反、完全相同或
15	// 其中一处为 null 都按同一规则拒绝，不选取其中一个值继续使用，交换字段顺序也
16	// 不改变拒绝结果，原文件保持原样。
17	func TestOpenRejectsDuplicateReleasedField(t *testing.T) {
18		// freeze 构造一条冻结记录，releasedFields 是原样拼接进记录的解除标记字段
19		// （可以写一个或多个，字段名写法与取值任意）；releaseInfo 在需要时补上
20		// 合法的解除原因与解除日期。
21		freeze := func(releaseInfo bool, releasedFields ...string) string {
