211		reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-10")
212		reg(t, s, "A-2", "凭证", "2020-01-01", "2025-06-30")
213		reg(t, s, "A-3", "单据", "2020-01-01", "2025-01-10")
214		if err := s.Freeze(FreezeInput{
215			ArchiveID: "A-1", FreezeID: "F-1", Reason: "诉讼", FrozenOn: MustParseDate("2025-01-05"),
216		}); err != nil {
217			t.Fatal(err)
218		}
219		// A-3 先冻结再解除、随后合法销毁，供损坏后验证“取回清册”同样整库失败。
220		if err := s.Freeze(FreezeInput{
221			ArchiveID: "A-3", FreezeID: "F-3", Reason: "保全", FrozenOn: MustParseDate("2025-01-06"),
222		}); err != nil {
223			t.Fatal(err)
224		}
225		if err := s.Release(ReleaseInput{
226			ArchiveID: "A-3", FreezeID: "F-3", Reason: "结案", ReleasedOn: MustParseDate("2025-01-08"),
227		}); err != nil {
228			t.Fatal(err)
229		}
230		if _, err := s.Destroy(DestructionRequest{
231			ApplicationID: "APP-3", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-3"},
232		}); err != nil {
233			t.Fatal(err)
234		}
235	
236		// 在 A-1 的冻结 F-1 里再写入一个解除标记：先保留原来的 released:false，
237		// 后面再写 released:true 并带上合法的解除原因和解除日期——普通解码会采用
238		// 后一个标记，把仍有效的冻结当成已解除。档案编号按排序保存，A-1 的冻结
239		// 记录是文件中第一个 released 字段。
240		good := readStateFile(t, dir)
241		corrupt := strings.Replace(good, `"released": false`,
242			`"released": false, "released": true, "release_reason": "结案", "released_on": "2025-01-08"`, 1)
243		if corrupt == good {
244			t.Fatal("未找到 A-1 冻结记录的解除标记位置，测试夹具失效")
245		}
246		writeStateFile(t, dir, corrupt)
247		corruptContent := readStateFile(t, dir)
248	
249		// 重新打开必须失败，错误指出档案编号、冻结编号，并说明重复的是解除标记 released。
250		s2, err := Open(dir)
251		if err == nil {
252			s2.Close()
253			t.Fatal("同一条冻结记录的保存内容中出现两个解除标记时，打开必须失败")
254		}
255		if !errors.Is(err, ErrCorruptState) ||
256			!strings.Contains(err.Error(), "A-1") ||
257			!strings.Contains(err.Error(), "F-1") ||
258			!strings.Contains(err.Error(), "released") ||
259			!strings.Contains(err.Error(), "解除标记") {
260			t.Fatalf("打开错误应为 ErrCorruptState 并指出档案 A-1 的冻结 F-1 的解除标记 released 重复，得到 %v", err)
261		}
262		if strings.Contains(err.Error(), "冻结编号") || strings.Contains(err.Error(), "冻结列表") {
263			t.Fatalf("错误信息不应误报为冻结编号或冻结列表重复，得到 %v", err)
264		}
265	
266		// 已打开实例：即使本次只操作没有问题的正常档案 A-2，也必须按整库损坏失败。
267		if h, found, err := s.History("A-2"); !errors.Is(err, ErrCorruptState) || found || h.ID != "" {
