269		}
270		if h, found, err := s.History("A-1"); !errors.Is(err, ErrCorruptState) || found || h.ID != "" {
271			t.Fatalf("损坏后 History 必须失败且不得给出部分历史: found=%v err=%v", found, err)
272		}
273		if m, found, err := s.GetManifest("APP-3"); !errors.Is(err, ErrCorruptState) || found || m.ApplicationID != "" {
274			t.Fatalf("损坏后 GetManifest 必须失败: found=%v err=%v %+v", found, err, m)
275		}
