287		}
288		if m, err := s.Destroy(DestructionRequest{
289			ApplicationID: "APP-9", ProcessedOn: MustParseDate("2025-06-30"), ArchiveIDs: []string{"A-2"},
290		}); !errors.Is(err, ErrCorruptState) || m.ApplicationID != "" {
291			t.Fatalf("损坏后 Destroy 必须失败且不得生成清册: %+v err=%v", m, err)
292		}
293		if m, err := s.Destroy(DestructionRequest{
294			ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
295		}); !errors.Is(err, ErrCorruptState) || m.ApplicationID != "" {
296			t.Fatalf("损坏后不得凭重复保存的解除标记销毁 A-1: %+v err=%v", m, err)
297		}
298		// 已成功申请的幂等重放同样不能取回原清册。
299		if m, err := s.Destroy(DestructionRequest{
300			ApplicationID: "APP-3", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-3"},
301		}); !errors.Is(err, ErrCorruptState) || m.ApplicationID != "" {
302			t.Fatalf("损坏后已成功申请的重放也必须失败且不得返回原清册: %+v err=%v", m, err)
303		}
304		if err := s.Register(RegisterInput{
305			ID: "A-4", Category: "凭证", Start: MustParseDate("2020-01-01"), End: MustParseDate("2025-06-30"),
306		}); !errors.Is(err, ErrCorruptState) {
307			t.Fatalf("损坏后 Register 必须失败: %v", err)
308		}
309		if err := s.Freeze(FreezeInput{
310			ArchiveID: "A-2", FreezeID: "F-X", Reason: "诉讼", FrozenOn: MustParseDate("2025-06-01"),
311		}); !errors.Is(err, ErrCorruptState) {
312			t.Fatalf("损坏后 Freeze 必须失败: %v", err)
313		}
314		if err := s.Release(ReleaseInput{
315			ArchiveID: "A-1", FreezeID: "F-1", Reason: "结案", ReleasedOn: MustParseDate("2025-01-08"),
316		}); !errors.Is(err, ErrCorruptState) {
317			t.Fatalf("损坏后 Release 必须失败: %v", err)
318		}
319		if _, err := s.Revise(ReviseInput{
320			RevisionID: "R-9", ArchiveID: "A-2",
321			OriginalEnd: MustParseDate("2025-06-30"), NewEnd: MustParseDate("2026-06-30"),
322			RevisedOn: MustParseDate("2025-06-01"), Reason: "延期",
323		}); !errors.Is(err, ErrCorruptState) {
324			t.Fatalf("损坏后 Revise 必须失败: %v", err)
325		}
