327		// 失败不得触发修复：不选取其中一个标记、不重新保存来消除重复，
328		// 原保存内容保持原样。
329		if got := readStateFile(t, dir); got != corruptContent {
330			t.Fatalf("失败后原保存内容被改动:\n%q", got)
331		}
