333		// 去掉重复的解除标记后，合法记录恢复可用：A-1 的冻结仍是损坏前那条未解除
334		// 冻结，不会被重复保存的 released:true 顶替；无关档案业务不受影响。
335		writeStateFile(t, dir, good)
336		h, found, err := s.History("A-1")
337		if err != nil || !found {
338			t.Fatalf("恢复后查询应成功: found=%v err=%v", found, err)
339		}
340		if len(h.Freezes) != 1 || h.Freezes[0].ID != "F-1" || h.Freezes[0].Released {
341			t.Fatalf("恢复后 A-1 应仍保留唯一一条未解除冻结 F-1: %+v", h.Freezes)
342		}
343		if r, err := s.Check(CheckRequest{
344			ApplicationID: "APP-8", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
345		}); err != nil || r.Status != CheckBlocked {
346			t.Fatalf("恢复后未解除冻结仍应阻止销毁 A-1: %+v err=%v", r, err)
347		}
348		if _, err := s.Destroy(DestructionRequest{
349			ApplicationID: "APP-2", ProcessedOn: MustParseDate("2025-06-30"), ArchiveIDs: []string{"A-2"},
350		}); err != nil {
351			t.Fatalf("恢复后无关档案应能正常办理销毁: %v", err)
352		}
353	}
