9	// 同一份档案自己的保存内容中，修订列表 revisions 最多只能出现一次：普通解码对
10	// 同名字段只保留最后一个值，同一份档案记录中若第一处保存着先延长、后缩短回
11	// 最初期限的两条修订（最初截止日 2025-01-10，R-1 延长到 2026-01-10，R-2 又
12	// 缩短回 2025-01-10），第二处又保存一个空列表，读取后当前截止日仍与最初期限
13	// 一致、保管库看似能正常打开，但两次修订已经消失，已占用的修订编号也可能被
14	// 重新用于新业务。Open 必须按保存记录损坏失败（ErrCorruptState），错误指出
15	// 档案编号，并说明重复的是修订列表 revisions 本身，不能误报为某个修订编号
16	// 重复；两处列表完全相同、分别保存不同修订、其中一处为空列表或 null 都按同一
17	// 规则拒绝，不合并、不挑选其中一份，互换两处的保存顺序也不能改变拒绝结果，
18	// 原文件保持原样。
19	func TestOpenRejectsDuplicateRevisionsField(t *testing.T) {
20		// 与任务场景一致的两条修订：先延长、后缩短回最初期限。
21		rev1 := `{"id":"R-1","old_end":"2025-01-10","new_end":"2026-01-10","revised_on":"2024-12-01","reason":"业务需要"}`
22		rev2 := `{"id":"R-2","old_end":"2026-01-10","new_end":"2025-01-10","revised_on":"2025-01-05","reason":"重新评估"}`
23		// rec 构造一份登记记录，revisionsFields 是原样拼接进记录的修订列表字段
24		// （可以写零个、一个或多个，字段名写法与列表内容任意）。当前截止日与
25		// 最初截止日都是 2025-01-10：若重复列表被静默覆盖，保管库看似正常。
26		rec := func(id string, revisionsFields ...string) string {
27			fields := `"id":"` + id + `","category":"合同","start":"2020-01-01","end":"2025-01-10","initial_end":"2025-01-10","destroyed":false`
28			for _, f := range revisionsFields {
29				fields += "," + f
30			}
31			return `{` + fields + `}`
32		}
33		state := func(archiveRec string) string {
34			return `{"version":1,"archives":{"A-1":` + archiveRec + `},"manifests":{}}`
35		}
36	
37		corrupt := map[string]string{
38			"先保存两条修订后保存空列表": state(rec("A-1", `"revisions":[`+rev1+`,`+rev2+`]`, `"revisions":[]`)),
39			"保存顺序相反同样拒绝":    state(rec("A-1", `"revisions":[]`, `"revisions":[`+rev1+`,`+rev2+`]`)),
40			"两处列表完全相同":      state(rec("A-1", `"revisions":[`+rev1+`,`+rev2+`]`, `"revisions":[`+rev1+`,`+rev2+`]`)),
41			"两处分别保存不同修订":    state(rec("A-1", `"revisions":[`+rev1+`]`, `"revisions":[`+rev2+`]`)),
42			"第二处为空列表":       state(rec("A-1", `"revisions":[`+rev1+`,`+rev2+`]`, `"revisions":[]`)),
43			"第一处为空列表":       state(rec("A-1", `"revisions":[]`, `"revisions":[`+rev1+`,`+rev2+`]`)),
44			"第二处为null":      state(rec("A-1", `"revisions":[`+rev1+`,`+rev2+`]`, `"revisions":null`)),
45			"第一处为null":      state(rec("A-1", `"revisions":null`, `"revisions":[`+rev1+`,`+rev2+`]`)),
46			"两处都为null":      state(rec("A-1", `"revisions":null`, `"revisions":null`)),
47			// 大小写写法（Revisions）与标准写法混用也算同一字段重复。
48			"大小写写法混用重复":   state(rec("A-1", `"Revisions":[`+rev1+`,`+rev2+`]`, `"revisions":[]`)),
49			"大小写写法混用顺序相反": state(rec("A-1", `"revisions":[`+rev1+`,`+rev2+`]`, `"Revisions":[]`)),
50			"修订列表出现三次":    state(rec("A-1", `"revisions":[`+rev1+`]`, `"revisions":[`+rev2+`]`, `"revisions":null`)),
51		}
52		// 转义写法需要在 JSON 文本中出现字面的反斜杠加 u0072（解码后即为字符 r，
53		// 字段名 evisions 前拼上它即为 revisions），用 Go 字符串拼接构造。
54		bs := "\\"
55		corrupt["Unicode转义字段名与直接字段名重复"] = state(rec("A-1", `"revisions":[`+rev1+`,`+rev2+`]`, `"`+bs+`u0072evisions":[]`))
56		corrupt["Unicode转义字段名与直接字段名重复顺序相反"] = state(rec("A-1", `"`+bs+`u0072evisions":[]`, `"revisions":[`+rev1+`,`+rev2+`]`))
57	
58		for name, content := range corrupt {
59			t.Run(name, func(t *testing.T) {
60				dir := t.TempDir()
61				writeStateFile(t, dir, content)
62	
63				s, err := Open(dir)
64				if err == nil {
65					s.Close()
66					t.Fatal("单份档案的保存内容中出现两次修订列表时不应打开成功")
67				}
68				if !errors.Is(err, ErrCorruptState) {
69					t.Fatalf("错误应可判定为 ErrCorruptState，得到 %v", err)
70				}
71				msg := err.Error()
72				if !strings.Contains(msg, "A-1") {
73					t.Fatalf("错误信息应指出档案编号 A-1，得到 %v", err)
74				}
75				if !strings.Contains(msg, "revisions") || !strings.Contains(msg, "修订列表") {
76					t.Fatalf("错误信息应说明重复的是修订列表 revisions，得到 %v", err)
77				}
78				// 不得误报为修订编号重复：重复的是列表字段本身，与修订编号无关。
79				if strings.Contains(msg, "修订编号") {
80					t.Fatalf("错误信息不应误报为修订编号重复，得到 %v", err)
81				}
82				if got := readStateFile(t, dir); got != content {
83					t.Fatalf("打开失败后原文件被改动:\n%q", got)
84				}
85			})
86		}
87	
88		// 对照组：没有修订的旧档案继续缺省修订列表；单次 null 或空列表继续表示没有
89		// 修订；现有能识别为修订列表的大小写写法与转义写法单独出现时继续可读；不同
90		// 档案各自的修订列表不合在一起计数。
91		t.Run("合法记录对照组", func(t *testing.T) {
92			legacy := func(id string) string {
93				return `{"id":"` + id + `","category":"合同","start":"2020-01-01","end":"2025-01-10","destroyed":false}`
94			}
95			valid := map[string]string{
96				"修订列表缺省":             `{"version":1,"archives":{"A-1":` + legacy("A-1") + `},"manifests":{}}`,
97				"revisions仅一次为null":  state(rec("A-1", `"revisions":null`)),
98				"仅有一个空列表":            state(rec("A-1", `"revisions":[]`)),
99				"大小写写法Revisions单独出现": state(rec("A-1", `"Revisions":[`+rev1+`,`+rev2+`]`)),
100				"大小写写法REVISIONS单独出现": state(rec("A-1", `"REVISIONS":[`+rev1+`,`+rev2+`]`)),
101				// 不同档案各自带自己的修订列表是正常保存格式，不合在一起计数。
102				"不同档案各自一个修订列表": `{"version":1,"archives":{"A-1":` + rec("A-1", `"revisions":[`+rev1+`,`+rev2+`]`) +
103					`,"A-2":{"id":"A-2","category":"凭证","start":"2020-01-01","end":"2026-06-30","initial_end":"2025-06-30","destroyed":false,"revisions":[{"id":"R-9","old_end":"2025-06-30","new_end":"2026-06-30","revised_on":"2025-01-02","reason":"延期"}]}},"manifests":{}}`,
104			}
105			// 转义写法单独出现：字段名以反斜杠加 u0072 转义写出，解码后仍是 revisions。
106			valid["Unicode转义字段名单独出现"] = state(rec("A-1", `"`+bs+`u0072evisions":[`+rev1+`,`+rev2+`]`))
107			for name, content := range valid {
108				t.Run(name, func(t *testing.T) {
109					dir := t.TempDir()
110					writeStateFile(t, dir, content)
111					s, err := Open(dir)
112					if err != nil {
113						t.Fatalf("合法记录应能打开: %v", err)
114					}
115					defer s.Close()
116				})
117			}
118		})
119	
120		// 只保存一次合法列表时，全部修订及原顺序、当前截止日、编号占用与相同提交
121		// 取回原记录的行为保持不变。
122		t.Run("合法列表内容完整保留", func(t *testing.T) {
123			dir := t.TempDir()
124			writeStateFile(t, dir, state(rec("A-1", `"revisions":[`+rev1+`,`+rev2+`]`)))
125			s, err := Open(dir)
126			if err != nil {
127				t.Fatalf("合法记录应能打开: %v", err)
128			}
129			defer s.Close()
130			h, found, err := s.History("A-1")
131			if err != nil || !found {
132				t.Fatalf("查询应成功: found=%v err=%v", found, err)
133			}
134			if len(h.Revisions) != 2 || h.Revisions[0].RevisionID != "R-1" || h.Revisions[1].RevisionID != "R-2" {
135				t.Fatalf("修订历史应按原顺序保留 R-1、R-2: %+v", h.Revisions)
136			}
137			if !h.InitialEnd.Equal(MustParseDate("2025-01-10")) || !h.RetentionEnd.Equal(MustParseDate("2025-01-10")) {
138				t.Fatalf("最初截止日与当前截止日都应为 2025-01-10: %+v", h)
139			}
140			// 编号占用不变：R-1 已被占用，改变内容的重提必须冲突。
141			if _, err := s.Revise(ReviseInput{
142				RevisionID: "R-1", ArchiveID: "A-1",
143				OriginalEnd: MustParseDate("2025-01-10"), NewEnd: MustParseDate("2027-01-10"),
144				RevisedOn: MustParseDate("2024-12-01"), Reason: "业务需要",
145			}); !errors.Is(err, ErrRevisionConflict) {
146				t.Fatalf("已占用的修订编号改内容重提应返回 ErrRevisionConflict，得到 %v", err)
147			}
148			// 相同提交取回原记录：内容完全相同的重试返回第一次成功的记录，不新增修订。
149			rec, err := s.Revise(ReviseInput{
150				RevisionID: "R-1", ArchiveID: "A-1",
151				OriginalEnd: MustParseDate("2025-01-10"), NewEnd: MustParseDate("2026-01-10"),
152				RevisedOn: MustParseDate("2024-12-01"), Reason: "业务需要",
153			})
154			if err != nil || rec.RevisionID != "R-1" || !rec.NewEnd.Equal(MustParseDate("2026-01-10")) {
155				t.Fatalf("相同提交应取回原修订记录: %+v err=%v", rec, err)
156			}
157			h, _, _ = s.History("A-1")
158			if len(h.Revisions) != 2 {
159				t.Fatalf("幂等重试不应新增修订记录: %+v", h.Revisions)
160			}
161		})
162	
163		// 已销毁档案同样适用：已销毁档案的保存内容中出现两次修订列表也按损坏拒绝；
164		// 只出现一次的合法已销毁档案继续可读。
165		t.Run("已销毁档案同样适用", func(t *testing.T) {
166			manifest := `{"application_id":"APP-1","processed_on":"2025-01-10","entries":[{"id":"A-1","category":"合同","start":"2020-01-01","end":"2025-01-10"}]}`
167			destroyedRec := func(revisionsFields ...string) string {
168				fields := `"id":"A-1","category":"合同","start":"2020-01-01","end":"2025-01-10","initial_end":"2025-01-10","destroyed":true,"manifest_id":"APP-1"`
169				for _, f := range revisionsFields {
170					fields += "," + f
171				}
172				return `{` + fields + `}`
173			}
174			stateWithManifest := func(archiveRec string) string {
175				return `{"version":1,"archives":{"A-1":` + archiveRec + `},"manifests":{"APP-1":` + manifest + `}}`
176			}
177	
178			dir := t.TempDir()
179			content := stateWithManifest(destroyedRec(`"revisions":[`+rev1+`,`+rev2+`]`, `"revisions":[]`))
180			writeStateFile(t, dir, content)
181			s, err := Open(dir)
182			if err == nil {
183				s.Close()
184				t.Fatal("已销毁档案的保存内容中出现两次修订列表时不应打开成功")
185			}
186			if !errors.Is(err, ErrCorruptState) ||
187				!strings.Contains(err.Error(), "A-1") ||
188				!strings.Contains(err.Error(), "revisions") {
189				t.Fatalf("打开错误应为 ErrCorruptState 并指出档案编号与修订列表 revisions，得到 %v", err)
190			}
191			if got := readStateFile(t, dir); got != content {
192				t.Fatalf("打开失败后原文件被改动:\n%q", got)
193			}
194	
195			// 对照：已销毁档案只保存一个修订列表时继续可读，清册归属不受影响。
196			dir2 := t.TempDir()
197			writeStateFile(t, dir2, stateWithManifest(destroyedRec(`"revisions":[`+rev1+`,`+rev2+`]`)))
198			s2, err := Open(dir2)
199			if err != nil {
200				t.Fatalf("合法的已销毁档案应能打开: %v", err)
201			}
202			defer s2.Close()
203			h, found, err := s2.History("A-1")
204			if err != nil || !found || !h.Destroyed || len(h.Revisions) != 2 {
205				t.Fatalf("已销毁档案的历史与修订记录应完整可查: %+v found=%v err=%v", h, found, err)
206			}
207		})
208	}
209	
210	// 保管库打开后保存内容才出现重复的修订列表：下一次使用有效输入查询、核对或办理
211	// 都必须按整库记录损坏失败——即使操作的是另一份正常档案——不返回部分结果、
212	// 不写入业务变更，原保存内容保持原样。
213	func TestDuplicateRevisionsFieldAfterOpenFailsAllOperations(t *testing.T) {
214		dir := t.TempDir()
215		s, err := Open(dir)
216		if err != nil {
217			t.Fatal(err)
218		}
219		defer s.Close()
220		reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-10")
221		reg(t, s, "A-2", "凭证", "2020-01-01", "2025-06-30")
222		// A-1 先延长、后缩短回最初期限：当前截止日与最初截止日相同，若重复保存的
223		// 空列表顶替了真实修订历史，保管库看似完全正常。
224		revise(t, s, "R-1", "A-1", "2025-01-10", "2026-01-10", "2024-12-01", "业务需要")
225		revise(t, s, "R-2", "A-1", "2026-01-10", "2025-01-10", "2025-01-05", "重新评估")
226	
227		// 在 A-1 的登记记录里再写入一个修订列表：先一个空列表、再是原来保存着
228		// 两条修订的列表——普通解码会只剩后一个，但两处保存本身已使记录不可信。
229		// 档案编号按排序保存，A-1 的记录是文件中第一个 revisions 字段。
230		good := readStateFile(t, dir)
231		corrupt := strings.Replace(good, `"revisions"`, `"revisions": [],
232	      "revisions"`, 1)
233		if corrupt == good {
234			t.Fatal("未找到 A-1 记录的修订列表位置，测试夹具失效")
235		}
236		writeStateFile(t, dir, corrupt)
237		corruptContent := readStateFile(t, dir)
238	
239		// 重新打开必须失败，错误指出档案编号并说明重复的是修订列表 revisions。
240		s2, err := Open(dir)
241		if err == nil {
242			s2.Close()
243			t.Fatal("单份档案的保存内容中出现两个修订列表时，打开必须失败")
244		}
245		if !errors.Is(err, ErrCorruptState) ||
246			!strings.Contains(err.Error(), "A-1") ||
247			!strings.Contains(err.Error(), "revisions") ||
248			!strings.Contains(err.Error(), "修订列表") {
249			t.Fatalf("打开错误应为 ErrCorruptState 并指出档案 A-1 的修订列表 revisions 重复，得到 %v", err)
250		}
251		if strings.Contains(err.Error(), "修订编号") {
252			t.Fatalf("错误信息不应误报为修订编号重复，得到 %v", err)
253		}
254	
255		// 已打开实例：即使本次只操作没有问题的正常档案 A-2，也必须按整库损坏失败。
256		if h, found, err := s.History("A-2"); !errors.Is(err, ErrCorruptState) || found || h.ID != "" {
257			t.Fatalf("损坏后查询无关档案也必须失败且无结论: found=%v err=%v", found, err)
258		}
259		if h, found, err := s.History("A-1"); !errors.Is(err, ErrCorruptState) || found || h.ID != "" {
260			t.Fatalf("损坏后 History 必须失败且不得给出部分历史: found=%v err=%v", found, err)
261		}
262		if r, err := s.Check(CheckRequest{
263			ApplicationID: "APP-9", ProcessedOn: MustParseDate("2025-06-30"), ArchiveIDs: []string{"A-2"},
264		}); !errors.Is(err, ErrCorruptState) || r.Status != "" || len(r.Results) != 0 {
265			t.Fatalf("损坏后 Check 必须失败且不得给出可以办理等结论或部分报告: %+v err=%v", r, err)
266		}
267		// 关键回归点：损坏状态下绝不能把被顶替的修订历史当成没有修订的依据，
268		// 在截止日当天给出可以办理甚至完成销毁。
269		if r, err := s.Check(CheckRequest{
270			ApplicationID: "APP-8", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
271		}); !errors.Is(err, ErrCorruptState) || r.Status != "" || len(r.Results) != 0 {
272			t.Fatalf("损坏后对 A-1 的核对也必须失败，不能误报可以办理: %+v err=%v", r, err)
273		}
274		if m, err := s.Destroy(DestructionRequest{
275			ApplicationID: "APP-9", ProcessedOn: MustParseDate("2025-06-30"), ArchiveIDs: []string{"A-2"},
276		}); !errors.Is(err, ErrCorruptState) || m.ApplicationID != "" {
277			t.Fatalf("损坏后 Destroy 必须失败且不得生成清册: %+v err=%v", m, err)
278		}
279		if m, err := s.Destroy(DestructionRequest{
280			ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
281		}); !errors.Is(err, ErrCorruptState) || m.ApplicationID != "" {
282			t.Fatalf("损坏后不得凭被顶替的修订历史销毁 A-1: %+v err=%v", m, err)
283		}
284		if err := s.Register(RegisterInput{
285			ID: "A-4", Category: "凭证", Start: MustParseDate("2020-01-01"), End: MustParseDate("2025-06-30"),
286		}); !errors.Is(err, ErrCorruptState) {
287			t.Fatalf("损坏后 Register 必须失败: %v", err)
288		}
289		if err := s.Freeze(FreezeInput{
290			ArchiveID: "A-2", FreezeID: "F-X", Reason: "诉讼", FrozenOn: MustParseDate("2025-06-01"),
291		}); !errors.Is(err, ErrCorruptState) {
292			t.Fatalf("损坏后 Freeze 必须失败: %v", err)
293		}
294		// 损坏状态下已消失的修订编号绝不能被重新用于新业务。
295		if _, err := s.Revise(ReviseInput{
296			RevisionID: "R-1", ArchiveID: "A-2",
297			OriginalEnd: MustParseDate("2025-06-30"), NewEnd: MustParseDate("2026-06-30"),
298			RevisedOn: MustParseDate("2025-06-01"), Reason: "延期",
299		}); !errors.Is(err, ErrCorruptState) {
300			t.Fatalf("损坏后 Revise 必须失败，已占用的修订编号不得重新使用: %v", err)
301		}
302	
303		// 失败不得触发修复：不合并两处列表、不挑选其中一份、不重新保存来消除重复，
304		// 原保存内容保持原样。
305		if got := readStateFile(t, dir); got != corruptContent {
306			t.Fatalf("失败后原保存内容被改动:\n%q", got)
307		}
308	
309		// 去掉重复的修订列表后，合法记录恢复可用：A-1 的两条修订仍按原顺序保留，
310		// 编号占用与幂等重放行为不变；无关档案业务不受影响。
311		writeStateFile(t, dir, good)
312		h, found, err := s.History("A-1")
313		if err != nil || !found {
314			t.Fatalf("恢复后查询应成功: found=%v err=%v", found, err)
315		}
316		if len(h.Revisions) != 2 || h.Revisions[0].RevisionID != "R-1" || h.Revisions[1].RevisionID != "R-2" {
317			t.Fatalf("恢复后 A-1 应仍保留两条修订 R-1、R-2: %+v", h.Revisions)
318		}
319		if _, err := s.Revise(ReviseInput{
320			RevisionID: "R-1", ArchiveID: "A-2",
321			OriginalEnd: MustParseDate("2025-06-30"), NewEnd: MustParseDate("2026-06-30"),
322			RevisedOn: MustParseDate("2025-06-01"), Reason: "延期",
323		}); !errors.Is(err, ErrRevisionConflict) {
324			t.Fatalf("恢复后修订编号 R-1 仍应被占用: %v", err)
325		}
326		if _, err := s.Destroy(DestructionRequest{
327			ApplicationID: "APP-2", ProcessedOn: MustParseDate("2025-06-30"), ArchiveIDs: []string{"A-2"},
328		}); err != nil {
329			t.Fatalf("恢复后无关档案应能正常办理销毁: %v", err)
330		}
331	}
332

