9	// 同一份保存记录的最外层最多只能出现一次清册集合：普通解码对同名字段只保留
10	// 最后一个值，最外层写了两次 manifests 时，前一处清册集合会被后一处整批替换。
11	// 例如 APP-1 的清册收录截止日为 2025-01-10 的已销毁档案，两处集合的条目、归属
12	// 都正确，处理日期分别为 2025-01-10 和 2025-01-11，两份内容都符合到期规则，
13	// 读取仍能成功，取回的处理日期却随保存顺序变化——已关闭清册的历史不能这样被
14	// 覆盖。Open 必须按保存记录损坏失败（ErrCorruptState），错误说明重复的是清册
15	// 集合 manifests 本身，而不是误报某个申请编号重复；两处集合内容完全一致、分别
16	// 只含不同申请、其中一处为空对象或 null 都按同一规则拒绝，不合并两处集合、不
17	// 挑选一份清册、不重新保存来消除重复，调整两处的保存顺序也不能改变拒绝结果，
18	// 原文件保持原样。
19	func TestOpenRejectsDuplicateManifestsField(t *testing.T) {
20		// arc 构造一份已销毁档案的登记记录；man 构造一份清册记录。
21		arc := func(id, category, end, app string) string {
22			return `{"id":"` + id + `","category":"` + category + `","start":"2020-01-01","end":"` + end +
23				`","initial_end":"` + end + `","destroyed":true,"manifest_id":"` + app + `","freezes":[]}`
24		}
25		man := func(app, processed, entries string) string {
26			return `{"application_id":"` + app + `","processed_on":"` + processed + `","entries":[` + entries + `]}`
27		}
28		entryA1 := `{"id":"A-1","category":"合同","start":"2020-01-01","end":"2025-01-10"}`
29		entryA2 := `{"id":"A-2","category":"凭证","start":"2020-01-01","end":"2025-06-30"}`
30		manA1Day10 := man("APP-1", "2025-01-10", entryA1)
31		manA1Day11 := man("APP-1", "2025-01-11", entryA1)
32		manA2 := man("APP-2", "2025-06-30", entryA2)
33		// escapedM 在 JSON 文本里是字符 m 的 Unicode 转义写法；拆成两段拼接，
34		// 避免转义序列在源码里以连续文本出现。
35		escapedM := "\\u00" + "6d"
36		a1 := arc("A-1", "合同", "2025-01-10", "APP-1")
37		a2 := arc("A-2", "凭证", "2025-06-30", "APP-2")
38		// state 用两个字段名写法与两处集合内容拼出最外层含两个清册集合的保存记录；
39		// 集合内容可以是任意 JSON 值（对象、空对象、null）。
40		state := func(archives, key1, manifests1, key2, manifests2 string) string {
41			return `{"version":1,"archives":` + archives + `,` + key1 + `:` + manifests1 + `,` + key2 + `:` + manifests2 + `}`
42		}
43		obj := func(entries string) string { return `{` + entries + `}` }
44	
45		corrupt := map[string]string{
46			"同一清册处理日期当天在前次日在后": state(obj(`"A-1":`+a1), `"manifests"`, obj(`"APP-1":`+manA1Day10), `"manifests"`, obj(`"APP-1":`+manA1Day11)),
47			"交换保存顺序次日在前当天在后":   state(obj(`"A-1":`+a1), `"manifests"`, obj(`"APP-1":`+manA1Day11), `"manifests"`, obj(`"APP-1":`+manA1Day10)),
48			"两处集合内容完全一致":       state(obj(`"A-1":`+a1), `"manifests"`, obj(`"APP-1":`+manA1Day10), `"manifests"`, obj(`"APP-1":`+manA1Day10)),
49			"两处分别只含不同申请":       state(obj(`"A-1":`+a1+`,"A-2":`+a2), `"manifests"`, obj(`"APP-1":`+manA1Day10), `"manifests"`, obj(`"APP-2":`+manA2)),
50			"两处分别只含不同申请顺序相反":   state(obj(`"A-1":`+a1+`,"A-2":`+a2), `"manifests"`, obj(`"APP-2":`+manA2), `"manifests"`, obj(`"APP-1":`+manA1Day10)),
51			"第二处为空对象":          state(obj(`"A-1":`+a1), `"manifests"`, obj(`"APP-1":`+manA1Day10), `"manifests"`, `{}`),
52			"第一处为空对象":          state(obj(`"A-1":`+a1), `"manifests"`, `{}`, `"manifests"`, obj(`"APP-1":`+manA1Day10)),
53			"第二处为null":         state(obj(`"A-1":`+a1), `"manifests"`, obj(`"APP-1":`+manA1Day10), `"manifests"`, `null`),
54			"第一处为null":         state(obj(`"A-1":`+a1), `"manifests"`, `null`, `"manifests"`, obj(`"APP-1":`+manA1Day10)),
55			"两处都为null":         state(obj(`"A-1":`+a1), `"manifests"`, `null`, `"manifests"`, `null`),
56			// "\u006d" 是字面的反斜杠+u006d，JSON 解码后才是字符 m，
57			// 与直接写出的 manifests 是同一个字段名。
58			"Unicode转义字段名与直接字段名重复": state(obj(`"A-1":`+a1), `"manifests"`, obj(`"APP-1":`+manA1Day10), `"`+escapedM+`anifests"`, obj(`"APP-1":`+manA1Day11)),
59			"大小写写法混用重复":            state(obj(`"A-1":`+a1), `"manifests"`, obj(`"APP-1":`+manA1Day10), `"Manifests"`, obj(`"APP-1":`+manA1Day11)),
60			"大小写写法混用顺序相反":          state(obj(`"A-1":`+a1), `"Manifests"`, obj(`"APP-1":`+manA1Day10), `"manifests"`, obj(`"APP-1":`+manA1Day11)),
61			"清册集合出现三次": `{"version":1,"archives":{"A-1":` + a1 + `},"manifests":{"APP-1":` + manA1Day10 +
62				`},"manifests":{"APP-2":` + manA2 + `},"manifests":{}}`,
63		}
64		// 转义写法需要字面反斜杠，单独构造。
65		corrupt["Unicode转义字段名表示同一字段"] = `{"version":1,"archives":{"A-1":` + a1 +
66			`},"manifests":{"APP-1":` + manA1Day10 + `},"` + escapedM + `anifests":{"APP-1":` + manA1Day11 + `}}`
67	
68		for name, content := range corrupt {
69			t.Run(name, func(t *testing.T) {
70				dir := t.TempDir()
71				writeStateFile(t, dir, content)
72	
73				s, err := Open(dir)
74				if err == nil {
75					s.Close()
76					t.Fatal("最外层出现两次清册集合时不应打开成功")
77				}
78				if !errors.Is(err, ErrCorruptState) {
79					t.Fatalf("错误应可判定为 ErrCorruptState，得到 %v", err)
80				}
81				msg := err.Error()
82				if !strings.Contains(msg, "manifests") || !strings.Contains(msg, "清册集合") {
83					t.Fatalf("错误信息应说明重复的是清册集合 manifests，得到 %v", err)
84				}
85				// 不得误报某个申请编号重复：这是集合字段本身重复，错误信息不涉及
86				// 任何具体申请编号，也不能使用集合内重复申请的措辞。
87				for _, id := range []string{"APP-1", "APP-2"} {
88					if strings.Contains(msg, id) {
89						t.Fatalf("错误信息不应误报申请编号 %s 重复，得到 %v", id, err)
90					}
91				}
92				if strings.Contains(msg, "多份清册") {
93					t.Fatalf("错误信息不应误报成同一申请编号对应多份清册，得到 %v", err)
94				}
95				if got := readStateFile(t, dir); got != content {
96					t.Fatalf("打开失败后原文件被改动:\n%q", got)
97				}
98			})
99		}
100	
101		// 对照组：清册集合只出现一次时继续可读——包括现有能识别为清册集合的大小写
102		// 写法与转义写法单独出现；清册集合缺省或仅一次为 null 的空库兼容行为不变；
103		// 多份清册内部各自带有的申请编号、处理日期和条目字段（甚至登记内容里名为
104		// manifests 的未知内部字段）是正常格式，不属于最外层的清册集合字段，不会
105		// 被误判。
106		t.Run("合法记录对照组", func(t *testing.T) {
107			valid := map[string]string{
108				"manifests只出现一次": `{"version":1,"archives":{"A-1":` + a1 + `},"manifests":{"APP-1":` + manA1Day10 + `}}`,
109				"多份清册内部字段同名": `{"version":1,"archives":{"A-1":` + a1 + `,"A-2":` + a2 + `},"manifests":{"APP-1":` +
110					manA1Day10 + `,"APP-2":` + manA2 + `}}`,
111				"大小写写法Manifests单独出现":    `{"version":1,"archives":{"A-1":` + a1 + `},"Manifests":{"APP-1":` + manA1Day10 + `}}`,
112				"大小写写法MANIFESTS单独出现":    `{"version":1,"archives":{"A-1":` + a1 + `},"MANIFESTS":{"APP-1":` + manA1Day10 + `}}`,
113				"清册集合缺省":                `{"version":1,"archives":{}}`,
114				"manifests仅一次为null":     `{"version":1,"archives":{},"manifests":null}`,
115				"登记内容里名为manifests的内部字段": `{"version":1,"archives":{"A-1":{"id":"A-1","category":"合同","start":"2020-01-01","end":"2025-01-10","destroyed":false,"freezes":[],"manifests":{"APP-9":{}}}},"manifests":{}}`,
116			}
117			// 转义写法需要字面反斜杠，单独构造。
118			valid["Unicode转义字段名单独出现"] = `{"version":1,"archives":{"A-1":` + a1 + `},"` + escapedM + `anifests":{"APP-1":` + manA1Day10 + `}}`
119			for name, content := range valid {
120				t.Run(name, func(t *testing.T) {
121					dir := t.TempDir()
122					writeStateFile(t, dir, content)
123					s, err := Open(dir)
124					if err != nil {
125						t.Fatalf("合法记录应能打开: %v", err)
126					}
127					defer s.Close()
128				})
129			}
130		})
131	}
132	
133	// 保管库打开后保存内容才出现重复的清册集合：下一次使用有效输入查询历史、取回
134	// 清册、销毁前核对与各项办理都必须按整库记录损坏失败——即使查询、操作的是另一
135	// 份正常档案或另一份正常清册——不返回部分历史、正常清册或可以办理的结论，不产生
136	// 业务变更，不合并两处集合、不挑选一份清册或重新保存来消除重复，原保存内容保持
137	// 原样。两处集合中的 APP-1 清册条目与归属都正确，处理日期分别为截止日当天与次日
138	// （均满足到期规则），结果不得随保存顺序变化。
139	func TestDuplicateManifestsFieldAfterOpenFailsAllOperations(t *testing.T) {
140		dir := t.TempDir()
141		s, err := Open(dir)
142		if err != nil {
143			t.Fatal(err)
144		}
145		defer s.Close()
146		reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-10")
147		reg(t, s, "A-2", "凭证", "2020-01-01", "2025-06-30")
148		reg(t, s, "A-3", "单据", "2020-01-01", "2025-01-10")
149		// A-1 在截止日当天合法销毁，生成 APP-1 清册。
150		if _, err := s.Destroy(DestructionRequest{
151			ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
152		}); err != nil {
153			t.Fatal(err)
154		}
155		// A-3 另以 APP-3 合法销毁，供损坏后验证无关清册的取回与重放也整库失败。
156		if _, err := s.Destroy(DestructionRequest{
157			ApplicationID: "APP-3", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-3"},
158		}); err != nil {
159			t.Fatal(err)
160		}
161		if m, found, err := s.GetManifest("APP-1"); err != nil || !found ||
162			!m.ProcessedOn.Equal(MustParseDate("2025-01-10")) {
163			t.Fatalf("损坏前清册应可取回且处理日期为当天: found=%v err=%v %+v", found, err, m)
164		}
165	
166		// 在最外层再写入一个清册集合：其中 APP-1 清册条目、归属都正确，只是处理
167		// 日期改为次日 2025-01-11（同样满足到期规则）。普通解码会只剩后一个集合，
168		// 取回的处理日期随保存顺序变成次日。
169		good := readStateFile(t, dir)
170		second := `"manifests": {
171	    "APP-1": {
172	      "application_id": "APP-1",
173	      "processed_on": "2025-01-11",
174	      "entries": [
175	        {
176	          "id": "A-1",
177	          "category": "合同",
178	          "start": "2020-01-01",
179	          "end": "2025-01-10"
180	        }
181	      ]
182	    }
183	  },
184	  "manifests"`
185		// 在真正的清册集合字段前再插入一个完整的 "manifests" 字段，成为最外层
186		// 的第二个清册集合（与档案集合重复测试相同的夹具做法），不依赖缩进风格。
187		corrupt := strings.Replace(good, `"manifests"`, second, 1)
188		if corrupt == good {
189			t.Fatal("未找到清册集合字段的位置，测试夹具失效")
190		}
191		writeStateFile(t, dir, corrupt)
192		corruptContent := readStateFile(t, dir)
193	
194		// 重新打开必须失败，错误说明重复的是清册集合 manifests，而不是误报 APP-1。
195		s2, err := Open(dir)
196		if err == nil {
197			s2.Close()
198			t.Fatal("最外层出现两个清册集合时，打开必须失败")
199		}
200		if !errors.Is(err, ErrCorruptState) ||
201			!strings.Contains(err.Error(), "manifests") ||
202			!strings.Contains(err.Error(), "清册集合") {
203			t.Fatalf("打开错误应为 ErrCorruptState 并说明清册集合 manifests 重复，得到 %v", err)
204		}
205	
206		// 已打开实例：即使本次只查询、核对或办理与重复清册无关的正常档案 A-2、
207		// 正常清册 APP-3，也必须按整库损坏失败。
208		if h, found, err := s.History("A-2"); !errors.Is(err, ErrCorruptState) || found || h.ID != "" {
209			t.Fatalf("损坏后查询无关档案也必须失败且无结论: found=%v err=%v", found, err)
210		}
211		if h, found, err := s.History("A-1"); !errors.Is(err, ErrCorruptState) || found || h.ID != "" {
212			t.Fatalf("损坏后 History 必须失败且不得给出销毁历史与清册: found=%v err=%v", found, err)
213		}
214		if m, found, err := s.GetManifest("APP-3"); !errors.Is(err, ErrCorruptState) || found || m.ApplicationID != "" {
215			t.Fatalf("损坏后取回无关清册也必须失败: found=%v err=%v %+v", found, err, m)
216		}
217		if m, found, err := s.GetManifest("APP-1"); !errors.Is(err, ErrCorruptState) || found || m.ApplicationID != "" {
218			t.Fatalf("损坏后 GetManifest 必须失败且不得返回任一集合中的清册: found=%v err=%v %+v", found, err, m)
219		}
220		if r, err := s.Check(CheckRequest{
221			ApplicationID: "APP-9", ProcessedOn: MustParseDate("2025-06-30"), ArchiveIDs: []string{"A-2"},
222		}); !errors.Is(err, ErrCorruptState) || r.Status != "" || len(r.Results) != 0 {
223			t.Fatalf("损坏后 Check 必须失败且不得给出可以办理等结论或部分报告: %+v err=%v", r, err)
224		}
225		// 关键回归点：损坏状态下绝不能按后一处（次日处理）集合或前一处给出
226		// “可以取回原清册”的结论。
227		if r, err := s.Check(CheckRequest{
228			ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
229		}); !errors.Is(err, ErrCorruptState) || r.Status != "" || r.Manifest != nil {
230			t.Fatalf("损坏后对 APP-1（当天）的核对也必须失败，不能附任一处集合中的清册: %+v err=%v", r, err)
231		}
232		if r, err := s.Check(CheckRequest{
233			ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-11"), ArchiveIDs: []string{"A-1"},
234		}); !errors.Is(err, ErrCorruptState) || r.Status != "" || r.Manifest != nil {
235			t.Fatalf("损坏后即使与后一处清册一致也不得取回: %+v err=%v", r, err)
236		}
237		if m, err := s.Destroy(DestructionRequest{
238			ApplicationID: "APP-9", ProcessedOn: MustParseDate("2025-06-30"), ArchiveIDs: []string{"A-2"},
239		}); !errors.Is(err, ErrCorruptState) || m.ApplicationID != "" {
240			t.Fatalf("损坏后 Destroy 必须失败且不得生成清册: %+v err=%v", m, err)
241		}
242		// 已成功申请的幂等重放（无论对应重复集合中的清册还是无关清册）都不能取回。
243		if m, err := s.Destroy(DestructionRequest{
244			ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
245		}); !errors.Is(err, ErrCorruptState) || m.ApplicationID != "" {
246			t.Fatalf("损坏后 APP-1 的幂等重放也必须失败且不得返回清册: %+v err=%v", m, err)
247		}
248		if m, err := s.Destroy(DestructionRequest{
249			ApplicationID: "APP-3", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-3"},
250		}); !errors.Is(err, ErrCorruptState) || m.ApplicationID != "" {
251			t.Fatalf("损坏后无关申请 APP-3 的重放也必须失败: %+v err=%v", m, err)
252		}
253		if err := s.Register(RegisterInput{
254			ID: "A-4", Category: "凭证", Start: MustParseDate("2020-01-01"), End: MustParseDate("2025-06-30"),
255		}); !errors.Is(err, ErrCorruptState) {
256			t.Fatalf("损坏后 Register 必须失败: %v", err)
257		}
258		if err := s.Freeze(FreezeInput{
259			ArchiveID: "A-2", FreezeID: "F-X", Reason: "诉讼", FrozenOn: MustParseDate("2025-06-01"),
260		}); !errors.Is(err, ErrCorruptState) {
261			t.Fatalf("损坏后 Freeze 必须失败: %v", err)
262		}
263		if err := s.Release(ReleaseInput{
264			ArchiveID: "A-2", FreezeID: "F-X", Reason: "结案", ReleasedOn: MustParseDate("2025-06-02"),
265		}); !errors.Is(err, ErrCorruptState) {
266			t.Fatalf("损坏后 Release 必须失败（整库损坏先于业务校验）: %v", err)
267		}
268		if _, err := s.Revise(ReviseInput{
269			RevisionID: "R-9", ArchiveID: "A-2",
270			OriginalEnd: MustParseDate("2025-06-30"), NewEnd: MustParseDate("2026-06-30"),
271			RevisedOn: MustParseDate("2025-06-01"), Reason: "延期",
272		}); !errors.Is(err, ErrCorruptState) {
273			t.Fatalf("损坏后 Revise 必须失败: %v", err)
274		}
275	
276		// 失败不得触发修复：不合并两处集合、不挑选一份清册或重新保存来消除重复，
277		// 原保存内容保持原样。
278		if got := readStateFile(t, dir); got != corruptContent {
279			t.Fatalf("失败后原保存内容被改动:\n%q", got)
280		}
281	
282		// 去掉重复的清册集合后，合法记录恢复可用：APP-1 仍是唯一的原清册（当天
283		// 处理），历史查询、按编号取回和相同日期及档案集合重提都取得原内容；
284		// 其他业务不受影响。
285		writeStateFile(t, dir, good)
286		h, found, err := s.History("A-1")
287		if err != nil || !found || h.Manifest == nil {
288			t.Fatalf("恢复后历史查询应成功并附原清册: found=%v err=%v", found, err)
289		}
290		if !h.Manifest.ProcessedOn.Equal(MustParseDate("2025-01-10")) {
291			t.Fatalf("恢复后历史中的清册应是 2025-01-10 的原内容，得到 %s", h.Manifest.ProcessedOn)
292		}
293		m, found, err := s.GetManifest("APP-1")
294		if err != nil || !found {
295			t.Fatalf("恢复后清册应可取回: found=%v err=%v", found, err)
296		}
297		if !m.ProcessedOn.Equal(MustParseDate("2025-01-10")) {
298			t.Fatalf("恢复后取回的应是唯一原清册（2025-01-10），得到 %s", m.ProcessedOn)
299		}
300		replay, err := s.Destroy(DestructionRequest{
301			ApplicationID: "APP-1", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
302		})
303		if err != nil || !replay.ProcessedOn.Equal(MustParseDate("2025-01-10")) {
304			t.Fatalf("恢复后相同日期与集合的重放应取回唯一原清册: %+v err=%v", replay, err)
305		}
306		if _, err := s.Check(CheckRequest{
307			ApplicationID: "APP-2", ProcessedOn: MustParseDate("2025-06-30"), ArchiveIDs: []string{"A-2"},
308		}); err != nil {
309			t.Fatalf("恢复后无关档案的核对应正常: %v", err)
310		}
311		if _, err := s.Destroy(DestructionRequest{
312			ApplicationID: "APP-2", ProcessedOn: MustParseDate("2025-06-30"), ArchiveIDs: []string{"A-2"},
313		}); err != nil {
314			t.Fatalf("恢复后无关档案应能正常办理销毁: %v", err)
315		}
316	}
317

