393		// 失败不得触发重新保存：损坏内容原样保留，不补原因、不删冻结。
394		if got := readStateFile(t, dir); got != corruptContent {
395			t.Fatalf("失败后原保存内容被改动:\n%q", got)
396		}
397	}
398	
399	// 损坏判断适用于库内全部已解除冻结，与本次办理名单无关：
400	// 异常记录挂在另一份已经销毁的档案下时，查询、核对、销毁其他档案
401	// 同样必须按记录损坏失败，不能把不完整解除信息作为正常历史返回。
402	func TestCorruptReleaseOnDestroyedArchiveFailsWholeVault(t *testing.T) {
403		dir := t.TempDir()
404		s, err := Open(dir)
405		if err != nil {
406			t.Fatal(err)
407		}
408		defer s.Close()
409		reg(t, s, "A-1", "合同", "2020-01-01", "2025-01-10")
410		reg(t, s, "D-1", "凭证", "2020-01-01", "2025-01-10")
411		if err := s.Freeze(FreezeInput{ArchiveID: "D-1", FreezeID: "F-D", Reason: "协查", FrozenOn: MustParseDate("2025-01-05")}); err != nil {
412			t.Fatal(err)
413		}
414		if err := s.Release(ReleaseInput{ArchiveID: "D-1", FreezeID: "F-D", Reason: "协查结束", ReleasedOn: MustParseDate("2025-01-06")}); err != nil {
415			t.Fatal(err)
416		}
417		if _, err := s.Destroy(DestructionRequest{
418			ApplicationID: "APP-D", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"D-1"},
419		}); err != nil {
420			t.Fatal(err)
421		}
422	
423		// 损坏发生在已销毁档案 D-1 身上（去掉解除日期）。
424		rewriteState(t, dir, func(doc map[string]any) {
425			freezes := doc["archives"].(map[string]any)["D-1"].(map[string]any)["freezes"].([]any)
426			delete(freezes[0].(map[string]any), "released_on")
427		})
428		corruptContent := readStateFile(t, dir)
429	
430		// 重新打开整个位置必须失败，错误指出 D-1 与 F-D。
431		s2, err := Open(dir)
432		if err == nil {
433			s2.Close()
434			t.Fatal("库内任一已解除冻结不完整时，打开必须失败")
435		}
436		if !errors.Is(err, ErrCorruptState) || !strings.Contains(err.Error(), "D-1") || !strings.Contains(err.Error(), "F-D") {
437			t.Fatalf("打开错误应为 ErrCorruptState 并指出 D-1/F-D，得到 %v", err)
438		}
439	
440		// 已打开的实例：即使本次只查询、核对、销毁与异常记录无关的 A-1，
441		// 也必须按整库损坏失败。
442		if _, found, err := s.History("A-1"); !errors.Is(err, ErrCorruptState) || found {
443			t.Fatalf("查询无关档案 A-1 也应返回 ErrCorruptState: found=%v err=%v", found, err)
444		}
445		if _, found, err := s.History("D-1"); !errors.Is(err, ErrCorruptState) || found {
446			t.Fatalf("查询已销毁的异常档案不得返回（不完整的）历史: found=%v err=%v", found, err)
447		}
448		if _, found, err := s.GetManifest("APP-D"); !errors.Is(err, ErrCorruptState) || found {
449			t.Fatalf("查询异常档案所属清册也应失败: found=%v err=%v", found, err)
450		}
451		if r, err := s.Check(CheckRequest{
452			ApplicationID: "APP-9", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
453		}); !errors.Is(err, ErrCorruptState) || r.Status != "" {
454			t.Fatalf("核对无关档案也应整次失败: %+v err=%v", r, err)
455		}
456		if m, err := s.Destroy(DestructionRequest{
457			ApplicationID: "APP-9", ProcessedOn: MustParseDate("2025-01-10"), ArchiveIDs: []string{"A-1"},
458		}); !errors.Is(err, ErrCorruptState) || m.ApplicationID != "" {
459			t.Fatalf("不得在损坏状态下生成清册: %+v err=%v", m, err)
460		}
461		if got := readStateFile(t, dir); got != corruptContent {
462			t.Fatalf("失败后原保存内容被改动:\n%q", got)
463		}
464	}
465

